import { v4 as uuidv4 } from "uuid";

// Types
export interface Task {
  id: string;
  title: string;
  description?: string;
  status: "Backlog" | "Todo" | "In Progress" | "Blocked" | "Done";
  priority: "Low" | "Medium" | "High" | "Urgent";
  tags: string[];
  projectId: string;
  createdAt: number;
  updatedAt: number;
}

export interface Project {
  id: string;
  name: string;
  createdAt: number;
  updatedAt: number;
}

class Storage {
  private projectsPath: string;
  private tasksPath: string;

  constructor(basePath: string) {
    this.projectsPath = `${basePath}/projects.json`;
    this.tasksPath = `${basePath}/tasks.json`;
    this.ensureFilesExist();
  }

  private ensureFilesExist(): void {
    const fs = await import("fs");
    if (!fs.existsSync(this.projectsPath)) {
      fs.writeFileSync(this.projectsPath, JSON.stringify({}, null, 2));
    }
    if (!fs.existsSync(this.tasksPath)) {
      fs.writeFileSync(this.tasksPath, JSON.stringify([], null, 2));
    }
  }

  private readProjects(): Project[] {
    const fs = await import("fs");
    const data = fs.readFileSync(this.projectsPath, "utf-8");
    return JSON.parse(data);
  }

  private writeProjects(projects: Project[]): void {
    const fs = await import("fs");
    fs.writeFileSync(this.projectsPath, JSON.stringify(projects, null, 2));
  }

  private readTasks(): Task[] {
    const fs = await import("fs");
    const data = fs.readFileSync(this.tasksPath, "utf-8");
    return JSON.parse(data);
  }

  private writeTasks(tasks: Task[]): void {
    const fs = await import("fs");
    fs.writeFileSync(this.tasksPath, JSON.stringify(tasks, null, 2));
  }

  // Project methods
  getAllProjects(): Project[] {
    return this.readProjects();
  }

  getProject(id: string): Project | undefined {
    return this.readProjects().find((p) => p.id === id);
  }

  createProject(name: string): Project {
    const project: Project = {
      id: uuidv4(),
      name,
      createdAt: Date.now(),
      updatedAt: Date.now(),
    };
    const projects = this.readProjects();
    projects.push(project);
    this.writeProjects(projects);
    return project;
  }

  updateProject(id: string, name: string): Project | null {
    const projects = this.readProjects();
    const index = projects.findIndex((p) => p.id === id);
    if (index === -1) return null;
    projects[index].name = name;
    projects[index].updatedAt = Date.now();
    this.writeProjects(projects);
    return projects[index];
  }

  deleteProject(id: string): boolean {
    const projects = this.readProjects();
    const tasks = this.readTasks();
    const projectIndex = projects.findIndex((p) => p.id === id);
    if (projectIndex === -1) return false;
    // Delete tasks belonging to this project
    const remainingTasks = tasks.filter((t) => t.projectId !== id);
    this.writeTasks(remainingTasks);
    this.writeProjects(projects.filter((p) => p.id !== id));
    return true;
  }

  // Task methods
  getAllTasks(): Task[] {
    return this.readTasks();
  }

  getTask(id: string): Task | undefined {
    return this.readTasks().find((t) => t.id === id);
  }

  getTasksByProject(projectId: string): Task[] {
    return this.readTasks().filter((t) => t.projectId === projectId);
  }

  createTask(
    title: string,
    description: string,
    status: "Backlog" | "Todo" | "In Progress" | "Blocked" | "Done",
    priority: "Low" | "Medium" | "High" | "Urgent",
    tags: string[],
    projectId: string
  ): Task | null {
    // Validate title length
    if (title.length > 120) {
      return null;
    }
    const task: Task = {
      id: uuidv4(),
      title,
      description: description || undefined,
      status,
      priority,
      tags: tags || [],
      projectId,
      createdAt: Date.now(),
      updatedAt: Date.now(),
    };
    const tasks = this.readTasks();
    tasks.push(task);
    this.writeTasks(tasks);
    return task;
  }

  updateTask(
    id: string,
    title: string,
    description: string,
    status: "Backlog" | "Todo" | "In Progress" | "Blocked" | "Done",
    priority: "Low" | "Medium" | "High" | "Urgent",
    tags: string[]
  ): Task | null {
    if (title.length > 120) {
      return null;
    }
    const tasks = this.readTasks();
    const index = tasks.findIndex((t) => t.id === id);
    if (index === -1) return null;
    tasks[index].title = title;
    tasks[index].description = description || undefined;
    tasks[index].status = status;
    tasks[index].priority = priority;
    tasks[index].tags = tags || [];
    tasks[index].updatedAt = Date.now();
    this.writeTasks(tasks);
    return tasks[index];
  }

  deleteTask(id: string): boolean {
    const tasks = this.readTasks();
    const index = tasks.findIndex((t) => t.id === id);
    if (index === -1) return false;
    tasks.splice(index, 1);
    this.writeTasks(tasks);
    return true;
  }
}

export default Storage;

import { z } from "zod";

export const projectSchema = z.object({
  name: z.string().min(1).max(100),
});

export const taskSchema = z.object({
  title: z.string().min(1).max(120),
  description: z.string().optional(),
  status: z.enum(["Backlog", "Todo", "In Progress", "Blocked", "Done"]),
  priority: z.enum(["Low", "Medium", "High", "Urgent"]),
  tags: z.array(z.string()).default([]),
  projectId: z.string().uuid(),
});

export const taskUpdateSchema = taskSchema.partial();

// Typeshared types
export type ProjectInput = z.infer<typeof projectSchema>;
export type TaskInput = z.infer<typeof taskSchema>;
export type TaskUpdateInput = z.infer<typeof taskUpdateSchema>;

import { Router, Request, Response } from "express";
import storage from "../storage";
import { projectSchema, type ProjectInput } from "../schemas";

