router.post("/", (req: Request, res: Response) => {
  try {
    const result = projectSchema.safeParse(req.body);
    if (!result.success) {
      return res.status(400).json({ error: "Invalid project data", details: result.error.format() });
    }
    const project: ProjectInput = result.data;
    const created = storage.createProject(project.name);
    res.status(201).json(created);
  } catch (err) {
    res.status(500).json({ error: "Internal server error" });
  }
});

