  const project = storage.getProject(req.params.id);
  if (!project) {
    return res.status(404).json({ error: "Project not found" });
  }
  res.json(project);
});

// PUT /api/projects/:id - update a project
router.put("/:id", (req: Request, res: Response) => {
  try {
    const result = projectSchema.safeParse(req.body);
    if (!result.success) {
      return res.status(400).json({ error: "Invalid project data", details: result.error.format() });
    }
    const project = storage.updateProject(req.params.id, result.data.name);
    if (!project) {
      return res.status(404).json({ error: "Project not found" });
    }
    res.json(project);
  } catch (err) {
    res.status(500).json({ error: "Internal server error" });
  }
});

// DELETE /api/projects/:id - delete a project
router.delete("/:id", (req: Request, res: Response) => {
  const deleted = storage.deleteProject(req.params.id);
  if (!deleted) {
    return res.status(404).json({ error: "Project not found" });
  }
  res.status(204).send();
});

