import { Router, Request, Response } from "express";
import storage from "../storage";
import { taskSchema, type TaskInput, type TaskUpdateInput } from "../schemas";

const router = Router();

// GET /api/tasks - list all tasks with filters and search
router.get("/", (req: Request, res: Response) => {
  let tasks = storage.getAllTasks();

  // Filter by projectId
  const projectId = req.query.projectId as string | undefined;
  if (projectId) {
    tasks = tasks.filter((t) => t.projectId === projectId);
  }

  // Filter by status
  const status = req.query.status as string | undefined;
  if (status) {
    tasks = tasks.filter((t) => t.status === status);
  }

  // Filter by priority
  const priority = req.query.priority as string | undefined;
  if (priority) {
    tasks = tasks.filter((t) => t.priority === priority);
  }

  // Filter by tag
  const tag = req.query.tag as string | undefined;
  if (tag) {
    tasks = tasks.filter((t) => t.tags.includes(tag));
  }

  // Free-text search over title and description
  const search = req.query.search as string | undefined;
  if (search) {
    const term = search.toLowerCase();
    tasks = tasks.filter(
      (t) =>
        t.title.toLowerCase().includes(term) ||
        (t.description && t.description.toLowerCase().includes(term))
    );
  }

  // Sort by createdAt descending
  tasks.sort((a, b) => b.createdAt - a.createdAt);

  // Page size 50 (initial page)
  const page = parseInt(req.query.page as string | "1") || 1;
  const pageSize = 50;
  const start = (page - 1) * pageSize;
  const end = start + pageSize;
  const paginated = tasks.slice(start, end);

  res.json({
    tasks: paginated,
    page,
    pageSize,
    total: tasks.length,
  });
});

// GET /api/tasks/project/:projectId - tasks for a specific project
router.get("/project/:projectId", (req: Request, res: Response) => {
  const tasks = storage.getTasksByProject(req.params.projectId);
  res.json({ tasks });
});

// POST /api/tasks - create a task
router.post("/", (req: Request, res: Response) => {
  try {
    const result = taskSchema.safeParse(req.body);
    if (!result.success) {
      return res.status(400).json({ error: "Invalid task data", details: result.error.format() });
    }
    const task: TaskInput = result.data;
    const created = storage.createTask(
      task.title,
      task.description || "",
      task.status,
      task.priority,
      task.tags,
      task.projectId
    );
    if (!created) {
      return res.status(400).json({ error: "Title must be 120 characters or fewer" });
    }
    res.status(201).json(created);
  } catch (err) {
    res.status(500).json({ error: "Internal server error" });
  }
});

// GET /api/tasks/:id - get a single task
router.get("/:id", (req: Request, res: Response) => {
  const task = storage.getTask(req.params.id);
  if (!task) {
    return res.status(404).json({ error: "Task not found" });
  }
  res.json(task);
});

// PUT /api/tasks/:id - update a task
