  try {
    const result = taskUpdateSchema.safeParse(req.body);
    if (!result.success) {
      return res.status(400).json({ error: "Invalid task data", details: result.error.format() });
    }
    const updated = storage.updateTask(
      req.params.id,
      result.data.title || "",
      result.data.description || "",
      result.data.status || "Backlog",
      result.data.priority || "Medium",
      result.data.tags || []
    );
    if (!updated) {
      return res.status(404).json({ error: "Task not found" });
