import express, { Request, Response, NextFunction } from "express";
import http from "http";
import { Server as SocketIOServer, Socket } from "socket.io";
import cors from "cors";
import projectsRoutes from "./routes/projects";
import tasksRoutes from "./routes/tasks";
import { createServer } from "vite";
import * as fs from "fs";
import * as path from "path";

// Types
import type { ProjectInput } from "./schemas";
import type { TaskInput, TaskUpdateInput } from "./schemas";

const app = express();
const PORT = process.env.PORT ? parseInt(process.env.PORT, 10) : 4317;

// Middleware
app.use(cors({ origin: true }));
app.use(express.json({ limit: "1mb" }));

// Routes
app.use("/api/projects", projectsRoutes);
app.use("/api/tasks", tasksRoutes);

// 404 handler
app.use((_req: Request, res: Response) => {
  res.status(404).json({ error: "Not found" });
});

// Error handler
app.use(
  (err: any, _req: Request, res: Response, _next: NextFunction) => {
    console.error("Unhandled error:", err);
    res.status(500).json({ error: "Internal server error" });
  }
);

// HTTP server and SSE + Socket.IO
const server = http.createServer(app);

// Initialize Socket.IO with CORS and basic options
const io = new SocketIOServer(server, {
  cors: {
    origin: true,
    methods: ["GET", "POST"],
  },
});

// Store online socket IDs per project for broadcasting
const projectSockets = new Map<string, Set<Socket>>();

io.on("connection", (socket: Socket) => {
  console.log("Client connected:", socket.id);

  socket.on("join-project", (projectId: string) => {
    if (!projectSockets.has(projectId)) {
      projectSockets.set(projectId, new Set());
    }
    projectSockets.get(projectId)!.add(socket);
    socket.join(projectId);
    console.log(`Socket ${socket.id} joined project ${projectId}`);
  });

  socket.on("leave-project", (projectId: string) => {
    if (projectSockets.has(projectId)) {
      projectSockets.get(projectId)!.delete(socket);
      if (projectSockets.get(projectId)!.size === 0) {
        projectSockets.delete(projectId);
      }
    }
    socket.leave(projectId);
    console.log(`Socket ${socket.id} left project ${projectId}`);
  });

  socket.on("disconnect", () => {
    console.log("Client disconnected:", socket.id);
    // Remove from all projects
    for (const [projectId, sockets] of projectSockets.entries()) {
      sockets.delete(socket);
      if (sockets.size === 0) {
        projectSockets.delete(projectId);
      }
      // Leave the socket from the room
      socket.leave(projectId);
    }
  });
});

// SSE helper: push event to all sockets in a project
