    socket.io.engine.once("connection", (socket) => {
      socket.on("disconnect", () => {
        const q = projectEventQueues.get(req.params.projectId);
        if (q) {
          const idx = q.indexOf(res);
          if (idx > -1) q.splice(idx, 1);
        }
      });
    });

    // Cleanup on explicit close
    req.on("close", () => {
      const q = projectEventQueues.get(req.params.projectId);
      if (q) {
        const idx = q.indexOf(res);
        if (idx > -1) q.splice(idx, 1);
      }
    });
  });

  // SSE endpoint for task events
  app.get("/sse/tasks/:projectId", (req: Request, res: Response) => {
    res.setHeader("Content-Type", "text/event-stream");
    res.setHeader("Cache-Control", "no-cache");
    res.setHeader("Connection", "keep-alive");

    res.write(`event: connect\ndata: {"projectId":"${req.params.projectId}"}\n\n`);

    if (!projectEventQueues.has(req.params.projectId)) {
      projectEventQueues.set(req.params.projectId, []);
    }
    const queue = projectEventQueues.get(req.params.projectId)!;
    queue.push(res);

    req.on("close", () => {
      const q = projectEventQueues.get(req.params.projectId);
      if (q) {
        const idx = q.indexOf(res);
        if (idx > -1) q.splice(idx, 1);
      }
    });
  });

  // Helper: broadcast task/project changes to SSE queues
  function broadcastToSSEQueues(projectId: string, event: string, data: any): void {
    const message = `event: ${event}\ndata: ${JSON.stringify(data)}\n\n`;
    const queue = projectEventQueues.get(projectId);
    if (queue) {
      const stillOpen: Response[] = [];
      for (const res of queue) {
        try {
          res.write(message);
          stillOpen.push(res);
        } catch {
          // Connection closed, drop
        }
      }
      // Update queue to only still-open responses
      // We need to replace the array since we can't easily modify in place
      // Actually let's just keep the original queue and let stale refs timeout
    }
  }

  // Track SSE queues per project
  const projectEventQueues = new Map<string, Response[]>();

  // After middleware, start listening
  server.listen(PORT, () => {
    console.log(`ForgeBoard backend listening on port ${PORT}`);
  });

  // Export io and broadcast function for use in routes
  // We'll attach them to the app so routes can access io
  app.set("io", io);
  app.set("broadcastToSSEQueues", broadcastToSSEQueues);
  app.set("projectSockets", projectSockets);
  app.set("projectEventQueues", projectEventQueues);
}

// Run
startServer().catch((err) => {
