  cors: {
    origin: true,
    methods: ["GET", "POST"],
  },
});

// Set the IO instance for publisher to use
setIO(io);

// Store online socket IDs per project for broadcasting
const projectSockets = new Map<string, Set<Socket>>();

io.on("connection", (socket: Socket) => {
  console.log("Client connected:", socket.id);

  socket.on("join-project", (projectId: string) => {
    if (!projectSockets.has(projectId)) {
      projectSockets.set(projectId, new Set());
    }
    projectSockets.get(projectId)!.add(socket);
    socket.join(projectId);
    console.log(`Socket ${socket.id} joined project ${projectId}`);
  });

  socket.on("leave-project", (projectId: string) => {
    if (projectSockets.has(projectId)) {
      projectSockets.get(projectId)!.delete(socket);
      if (projectSockets.get(projectId)!.size === 0) {
        projectSockets.delete(projectId);
      }
    }
    socket.leave(projectId);
    console.log(`Socket ${socket.id} left project ${projectId}`);
  });

  socket.on("disconnect", () => {
    console.log("Client disconnected:", socket.id);
    // Remove from all projects
    for (const [projectId, sockets] of projectSockets.entries()) {
      sockets.delete(socket);
      if (sockets.size === 0) {
        projectSockets.delete(projectId);
      }
      // Leave the socket from the room
      socket.leave(projectId);
    }
  });
});

