import { Server as SocketIOServer, Socket } from "socket.io";
import type { Server as ExpressServer } from "express";
import type { Response } from "express";

/// Event types
export type SSEEvent =
  | "task-created"
  | "task-updated"
  | "task-deleted"
  | "project-created"
  | "project-updated"
  | "project-deleted";

/// SSE message format
export interface SSEMessage {
  type: SSEEvent;
  data: any;
  projectId: string;
  timestamp: number;
}

/// Per-project SSE subscription queue
type SSEQueue = Response[];

const sseQueues = new Map<string, SSEQueue>();

/**
 * Subscribe a response object to receive SSE events for a project.
 * Called when client connects to /sse/projects/:projectId or /sse/tasks/:projectId
 */
export function subscribeSSE(projectId: string, res: Response): void {
  if (!sseQueues.has(projectId)) {
    sseQueues.set(projectId, []);
  }
  const queue = sseQueues.get(projectId)!;
  if (!queue.includes(res)) {
    queue.push(res);
  }
}

/**
 * Unsubscribe a response from receiving SSE events for a project.
 */
export function unsubscribeSSE(projectId: string, res: Response): void {
  const queue = sseQueues.get(projectId);
  if (queue) {
    const idx = queue.indexOf(res);
    if (idx > -1) {
      queue.splice(idx, 1);
    }
  }
}

/**
 * Broadcast an SSE event to all subscribers for a project.
 */
export function broadcastSSE(projectId: SSEEvent, data: any, projectIdKey: string): void {
  const message =
    `event: ${projectId}\ndata: ${JSON.stringify({ event: projectId, data, projectId: projectIdKey, timestamp: Date.now() })}\n\n`;
  const queue = sseQueues.get(projectIdKey);
  if (queue) {
    const stillOpen: Response[] = [];
    for (const res of queue) {
      try {
        res.write(message);
        stillOpen.push(res);
      } catch {
        // Connection closed, drop
      }
    }
    // Replace queue with still-open responses
    sseQueues.set(projectIdKey, stillOpen);
  }
}

/// Socket.IO server reference
let io: SocketIOServer | null = null;

/**
 * Set the Socket.IO server instance.
 */
export function setIO(server: SocketIOServer): void {
  io = server;
}

/// Emit a Socket.IO event to a project room
export function emitToProject(room: string, event: string, data: any): void {
  if (io) {
    io.to(room).emit("message", {
      type: event,
      data,
      timestamp: Date.now(),
    });
  }
}

/// Get all SSE queues for debugging/monitoring
export function getSSEQueues(): Map<string, SSEQueue> {
  return sseQueues;
}

export default { broadcastSSE, subscribeSSE, unsubscribeSSE, emitToProject, getSSEQueues };
